import React, { useState, useEffect } from "react";
import AchievementsPanel from './AchievementsPanel';

export default function AdminDashboard({ reports, token, setMsg }) {
  const [ngos, setNgos] = useState([]);
  const [events, setEvents] = useState([]);
  const [eventStats, setEventStats] = useState([]);
  const [topVolunteers, setTopVolunteers] = useState([]);
  const [topDonors, setTopDonors] = useState([]);
  const [badges, setBadges] = useState([]);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  // Generic fetch handler
  const loadData = async (endpoint, setter, field, errMsg) => {
    if (!token) return setMsg("Login as admin first");
    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error(errMsg);
      const data = await res.json();
      setter(data[field] || []);
    } catch (e) {
      console.error(e);
      setMsg(e.message || errMsg);
    }
  };

  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error("Failed to delete NGO");
      setMsg("NGO removed successfully");
      setNgos(prev => prev.filter(n => n.id !== id));
    } catch (e) {
      console.error(e);
      setMsg(e.message);
    }
  };

  // Load Quick Links data when component mounts
  useEffect(() => {
    if (token) {
      loadData('/api/actions/top-volunteers', setTopVolunteers, 'top', 'Failed to load top volunteers');
      loadData('/api/actions/top-donors', setTopDonors, 'top', 'Failed to load top donors');
      loadData('/api/actions/badges', setBadges, 'badges', 'Failed to load badges');
    }
  }, [token]);

  return (
    <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start' }}>
      
      {/* LEFT PANEL */}
      <div style={{ flex: 1 }}>
        <AchievementsPanel token={token} me={{ points: reports?.adminPoints || 0 }} role="user" setMsg={setMsg} />

        <h3>Admin Reports</h3>
        <div className="cards">
          <div className="stat-card">
            <div className="stat-num">
              {reports?.donations?.reduce((s, d) => s + parseFloat(d.amount || 0), 0) || "-"}
            </div>
            <div className="stat-label">Total Donation Amount (₹)</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.volunteers?.length || 0}</div>
            <div className="stat-label">Total Volunteers</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.feedbacks?.length || 0}</div>
            <div className="stat-label">Feedbacks</div>
          </div>
        </div>

        {/* EVENTS LIST */}
        {events.length > 0 && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered Events</h4>
            {events.map(e => (
              <div key={e.id} style={{ padding: 8, background: "#fff", borderRadius: 8, marginBottom: 8 }}>
                <strong>{e.title}</strong>
                <div style={{ fontSize: 13, color: "#666" }}>{e.date}</div>
              </div>
            ))}
          </div>
        )}

        {/* EVENT STATS */}
        {eventStats.length > 0 && (
          <div style={{ marginTop: 20 }}>
            <h4>Event Statistics</h4>
            {eventStats.map(ev => (
              <div key={ev.id} style={{ display: "flex", gap: 12, alignItems: "center", padding: 8, background: "#fff", borderRadius: 8, marginBottom: 8 }}>
                <img src={ev.image_url || "https://via.placeholder.com/120x80"} alt="ev" style={{ width: 100, height: 64, objectFit: "cover", borderRadius: 6 }} />
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600 }}>{ev.title}</div>
                  <div style={{ fontSize: 13, color: "#666" }}>
                    Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* NGO LIST */}
        {ngos.length > 0 && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered NGOs</h4>
            {ngos.map(n => (
              <div key={n.id} style={{ padding: 8, background: "#fff", borderRadius: 8, marginBottom: 8, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <strong>{n.name}</strong>
                  <div style={{ fontSize: 13, color: "#666" }}>{n.email}</div>
                </div>
                <button
                  style={{ padding: "6px 12px", background: "red", color: "white", border: "none", borderRadius: 6, cursor: "pointer" }}
                  onClick={() => deleteNgo(n.id)}
                >
                  Remove
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* RIGHT PANEL: Quick Links Boxes */}
      <div style={{ width: 300, flexShrink: 0, display: 'flex', flexDirection: 'column', gap: 16, position: 'sticky', top: 16 }}>
        
        {/* Top Volunteers */}
        <div style={{ background: '#fff', padding: 12, borderRadius: 10, boxShadow: '0 6px 20px rgba(2,6,23,0.04)' }}>
          <h4>Top Volunteers</h4>
          {topVolunteers.length > 0 ? topVolunteers.map(v => (
            <div key={v.id} style={{ padding: 6, borderBottom: '1px solid #eee' }}>
              <strong>{v.name}</strong> — Points: {v.points}
            </div>
          )) : <p>No data available.</p>}
        </div>

        {/* Top Donors */}
        <div style={{ background: '#fff', padding: 12, borderRadius: 10, boxShadow: '0 6px 20px rgba(2,6,23,0.04)' }}>
          <h4>Top Donors</h4>
          {topDonors.length > 0 ? topDonors.map(d => (
            <div key={d.id} style={{ padding: 6, borderBottom: '1px solid #eee' }}>
              <strong>{d.name}</strong> — ₹{d.total_donated}
            </div>
          )) : <p>No data available.</p>}
        </div>

        {/* Badges */}
        <div style={{ background: '#fff', padding: 12, borderRadius: 10, boxShadow: '0 6px 20px rgba(2,6,23,0.04)' }}>
          <h4>Badges</h4>
          {badges.length > 0 ? badges.map(b => (
            <div key={b.id} style={{ padding: 6, borderBottom: '1px solid #eee' }}>
              <strong>{b.name}</strong> — {b.description}
            </div>
          )) : <p>No badges available.</p>}
        </div>

      </div>
    </div>
  );
}
